INSERT OR IGNORE INTO posts (slug, title, excerpt, body, cover_image, category, author_name, published_at, status) VALUES
  ('what-on-the-go-reporting-means-for-your-restaurant', 'Reporting On-the-Go for Restaurants', 'As a business owner, it’s natural to worry about the health and wellness of your restaurant. Especially when you can’t be on the premises all the time, it’s natural for restaurant managers to look for other ways to...', '[{"type":"p","text":"As a business owner, it’s natural to worry about the health and wellness of your restaurant. Especially when you can’t be on the premises all the time, it’s natural for restaurant managers to look for other ways to ascertain that their restaurant is making the best possible operational decisions, even when theyre not being monitored by people higher up on the chain of command."},{"type":"p","text":"Now advanced technology is here to keep you from wasting time babysitting every minute aspect of your restaurant. With vendors like eatOS, you get advanced Point of Sale systems that do the data sourcing and analysis for you. Save time, money and effort, with our restaurant POS reports and refocus instead on optimizing every aspect of your business, from the very top all the way down."},{"type":"h2","text":"What do you get with eatOS?"},{"type":"p","text":"Experience a product mix like no other, with all of the features you’ve been craving to run your business right. With our menu analytics, labor data, daily sales reports and other capabilities, you can effectively run your business from any device connected to the network. eatOS Point of Sale is the best way to comprehensively view and manage all of this information."},{"type":"h2","text":"Advanced Insight and Reporting"},{"type":"p","text":"Get information in real-time with our merchant app. A cloud-based storage system means that you can access the dashboard from any Point of Sale, web browser or mobile device as long as you’re connected to the internet."},{"type":"p","text":"In addition, we offer multi-device support so the dashboard works on any iOS or Android device. Get the most out of our software integrations, even on the go, and be able to access help centers or restaurant data from any deviceincluding your smartphone. Support more reasonable expectations and a better work/life balance when you have eatOS devices superior capabilities."},{"type":"h2","text":"Practical Insights"},{"type":"p","text":"Review and manage your most relevant and important data in real-time. With the information that we gather automatically based on intake and output, eatOS devices generate reports that help you make rounded business decisions. You’ll be able to:"},{"type":"p","text":"1. Save money"},{"type":"p","text":"2. Increase work efficiency"},{"type":"p","text":"3. Prevent over- or understaffing based on past traffic"},{"type":"p","text":"4. Reference sales breakdowns for better rates with vendors"},{"type":"p","text":"5. Create better marketing and promotional material"},{"type":"p","text":"6. Improve overall operations"},{"type":"p","text":"and more with eatOS."},{"type":"h2","text":"Multi-Location Reporting"},{"type":"p","text":"Break down store-level details or view a complete overview of all your locations for comparative analysis. You can customize the results and even remotely control access for employees on every level of the management chain. Remote control capabilities are especially useful for businesses looking to scale or expand because you can manage multiple locations from the same easy-to-use interface. When you’re looking to open up multiple venues, you need to find an alternative to being everywhere at once. eatOS has those solutions."},{"type":"h2","text":"Comparative Reporting"},{"type":"p","text":"Comprehensive details about the wellness of your business work best when paired with the ability to track progress over time and view multiple data sets so you can see which tactics and managerial decisions work best. Check your current stats against past performance or compare sales between venues to get an accurate view of how you’re doing. You can even pre-configure the dashboard to generate these reports in an easy-to-read format for your utmost convenience."},{"type":"p","text":"Fast, real-time, cloud-based services are the best option for every restaurant. With the ability to optimize all operations from anywhere, managing your business effectively has never been simpler. It’s critical in this modern era to be able to have control of your business decisions no matter what or where you are."},{"type":"p","text":"With eatOS, your restaurant is wherever you are. Learn more about our on-the-go reporting features and everything else we have to offer when you book a demo with us."},{"type":"p","text":"#CloudTechnology #eatOS #RestaurantBusiness #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_a62e905be03d4470a274d42a18ca6d74~mv2.jpeg', 'Point of Sale', 'eatOS Staff', '2018-08-29', 'published'),
  ('why-your-restaurant-needs-a-kitchen-display-system', 'Every Restaurant Needs a Kitchen Display System', 'When you think of streamlining restaurant operations, your mind might jump to improving server training or introducing mobile ordering for customers’ convenience. Keep in mind it’s just as important to optimize your...', '[{"type":"p","text":"When you think of streamlining restaurant operations, your mind might jump to improving server training or introducing mobile ordering for customers’ convenience. Keep in mind it’s just as important to optimize your back-of-house as it is to maintain composure upfront on the service floor. Kitchen Display System are gaining prominence in the marketplace as they integrate into your existing technology ecosystem to bring your commercial kitchen to brand new heights."},{"type":"h2","text":"Features and Perks"},{"type":"p","text":"eatOS powers kitchen-grade hardware that’s prepared to handle the heat. With a touch screen and three-year warranty, our KDS provides cost-effective solutions to your commercial kitchen’s blind spots. Get benefits like:"},{"type":"p","text":"1. Multi-lingual support so every member of your team can use the device in their native tongue for maximum and equitable convenience."},{"type":"p","text":"2. Prep station routing to automatically send the order to the correct part of the kitchen, while real-time synchronization keeps everyone working in tandem."},{"type":"p","text":"3. Seamless connectivity to the rest of your network, including the Kiosk, mobile Point of Sales, and your other ordering channels. We optimize the queue, so everyone gets their order in a timely fashion."},{"type":"p","text":"4. Forget about network connectivity issues; offline mode keeps the kitchen running if the internet goes down and automatically syncs back to the cloud when you’re back online."},{"type":"p","text":"5. Reduce printing costs when you go digital. It’s an environmentally friendly option and wins you points with customers who prefer their companies green."},{"type":"h2","text":"Why Do You Need a Kitchen Display System?"},{"type":"p","text":"The upfront cost of a KDS installation might put you on edge, but it shouldn’t. Like all good technology, the initial investment is offset by the ROI. With increased flexibility and digitization, you cut through human error and concerns about social distance while hastening operations, so in no time, the KDS starts to pay for itself."},{"type":"p","text":"Printed or handwritten tickets get lost, damaged, or smudged; that coupled with human error guarantees that your order accuracy improves with a KDS. Tickets appear onscreen as soon as they’re submitted, which improves turn times for speedier service overall."},{"type":"p","text":"COVID-19 has also introduced the sheer necessity of station routing capabilities. Already a perk because it streamlined service, now this feature allows line cooks to take their places at the beginning of a shift and not have to intermingle with their coworkers, thus reducing their risk of transmission. This additionally reduces contact between servers and back of house workers, which has become more of a necessity, especially in restaurants where dine-in service is restricted but ongoing."},{"type":"p","text":"Although KDS work great on their own, you can supplement their effectiveness with added components. Impact printers work great if you decide to stick to physical tickets in addition to a screen, as they print louder than normal to be heard over the noise. Depending on whether you buy Kitchen Display Screens for every station or mount one for them to share, you might also consider a wall mount or stand for the tablet for equitable access."},{"type":"p","text":"Get superior software that offers a customizable interface while meal coursing capabilities give customers as many benefits as you get from the equation’s business side. Learn how our KDS integrates into your current operations to make restaurant management simple and more capable at the same time. Book a demo with eatOS today."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #kitchendisplaysystem #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_5a99aff118ea483c8094c7bc726ca195~mv2.png', 'Kitchen Operations', 'eatOS Staff', '2018-08-23', 'published'),
  ('can-your-restaurant-handle-reservations', 'Can Your Restaurant Handle Reservations?', 'COVID-19 influenced the restaurant industry in unexpected ways. Some trends died while others flourished out of the blue. Reservations have become important, both because of new financial constraints caused by the...', '[{"type":"p","text":"COVID-19 influenced the restaurant industry in unexpected ways. Some trends died while others flourished out of the blue. Reservations have become important, both because of new financial constraints caused by the pandemic and evolving consumer preferences which is why having the right POS system for restaurants is important."},{"type":"p","text":"Because reservations do save money. You’ll reduce your labor costs because you’ll know exactly how much staff to schedule that night. Maximize your tables, too, by anticipating turn-times more accurately. Is your current reservation software up for this new reliance on call-ahead seating?"},{"type":"p","text":"Photo by Hassan OUAJBIR on Unsplash"},{"type":"h2","text":"Make Reservations a Success"},{"type":"p","text":"Given that they’ve become so relevant, your reservation software needs to be equipped to handle the strain. Perhaps you’ve never done reservations before but are introducing them because of COVID-19. Maybe you’re just putting more pressure on channels that you already used. Either way, optimize your system to get the most ROI possible."},{"type":"p","text":"1. Send reminders about guest reservations via text or email to reduce no-shows, which eat up profit."},{"type":"p","text":"2. Implement fees for late cancellations and no-shows to encourage communication."},{"type":"p","text":"3. Use reservation notes for allergies, preferences and other requests."},{"type":"p","text":"4. Open reservations on multiple platforms. For example, you may already have a button to book a table on your website. You should also get on databases like Google and Yelp to expand your pool of potential customers."},{"type":"p","text":"You get more with advanced Point of Sales. For example, integrating your reservation software with guest profiles improves your overall sales data. You can identify your most frequent visitors and what your most loyal guests prefer. Capitalize on these opportunities to create a customer experience tailored for your audience. It shows your regulars that you’re paying attention and care about them, too. Smart reservation software supports customer relationship management to build a better business overall. That’s why upgrading, and creating the best reservation management experience you can, is so important."},{"type":"h2","text":"Better Tech Drives Success"},{"type":"p","text":"Point of Sale systems can do much more than just take payments now. When they’re powered by software like eatOS, you’ll get cloud-based capabilities that provide increased security and efficiency. Being able to run your restaurant from one smart hub makes everyone’s job easier. Communication improves between the front and back of house. This way, walk-in customers have a better estimate on wait times and servers can track which tables have their food. You’re also modernizing the experience to meet today’s customer expectations, which is important in a tough market like this."},{"type":"p","text":"Contemporary Point of Sales also takes up less room in the restaurant itself, thereby letting you optimize your floor space with more tables. Given that social distance regulations are still in place, even in states that allow full capacity, why not make the most of what you’ve got?"},{"type":"p","text":"Photo by krutarth shah on Unsplash"},{"type":"h2","text":"Reservations Made Easy"},{"type":"p","text":"Instead of big, bulky devices, eatOS Point of Sale runs on tablets, via self-service hardware like Kiosks, and even on mobile devices with the help of QR codes. Good reservation software improves customer relationships and loyalty, and that drives more frequent visits. Repeat guests then spend more on average. Success begets success, and it all starts with a smarter POS."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#Reservations #eatOS #PointofSaleforRestaurants #Covid19Pandemic #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_432ba0dc11d546e5b681bfda87dfb3ba~mv2.jpg', 'Workforce Management', 'eatOS Staff', '2018-08-16', 'published'),
  ('eatos-restaurant-management-made-simple', 'eatOS: Restaurant Management Made Simple', 'Welcome to eatOS, where we understand that the best businesses run on speed and efficiency. That’s why we’ve made it our mission to outfit you with the most state-of-the-art technology available, so you can manage all...', '[{"type":"p","text":"Welcome to eatOS, where we understand that the best businesses run on speed and efficiency. That’s why we’ve made it our mission to outfit you with the most state-of-the-art technology available, so you can manage all the moving parts of your restaurant without any of the usual hassle. We do the work so you don’t have to."},{"type":"h2","text":"Cutting-Edge Technology"},{"type":"p","text":"Our Point of Sale system, and the other associated devices that we offer, was designed with your needs in mind. We understand that smooth restaurant management in the twenty-first century means putting your faith in web-based services like tableside ordering, mobile browsing, pay-at-table capabilities, fast and safe transactions and more. That’s why we worked so hard to provide a Point of Sale solution just for you."},{"type":"p","text":"Terminals powered by eatOS automatically sync the data from all the tablets, iPads and other devices connected to your network onto one easy-to-use screen so you can track your sales and reporting in real time. Our intuitive system makes it easy to train new employees so you dont waste money on a lengthy hiring process, a consideration that’s critical for an industry famous for its high employee turnover rates."},{"type":"h2","text":"What exactly is so easy about eatOS?"},{"type":"p","text":"eatOS is a restaurant POS software, we made it simple to manage your employees and track your data. We don’t just consolidate information on the main hubwe also do the analytics and reporting for you. We make your budgeting and operational decisions easier than ever before. With auto-generated reporting features, you can see your slowest and busiest times of the day or year, which employees outperform, and moreall with the tap of a single screen. The ability to view your restaurant’s performance over time based on a variety of metrics gives you critical information that influences budgeting and hiring decisions, promotions and more. eatOS’s interface makes it easier than ever to get your job done right."},{"type":"p","text":"Moreover, you can view these statistics from anywhere and at any time. With the right permissions, you can see the health of the business even without being on-site, which allows you to relax instead of having to constantly be hands-on monitoring the customer experience. Sign in from anywhere theres internet and easily view all of this information from the comfort of your smartphone or tablet. You can also update your devices from afar, or set them to automatically do so when the restaurant is closed so your operations never miss a beat."},{"type":"p","text":"Connecting with your guests and providing them with a seamless restaurant experience is critical for restaurant. In the time of COVID-19, it’s especially vital that you have a reliable avenue to manage customer relationships and engage with the community in a meaningful way. That’s why we focus so hard on giving you the ability to better manage your customer relationships as well as all other aspects of the restaurant, from your employees to your menu to your sales and beyond."},{"type":"p","text":"Restaurant management has never been simpler, more accessible or better for business. Get a demo today and find out why restaurant owners all over are upgrading their hard- and software to eatOS."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #eatOS #RestaurantBusiness #CloudTechnology #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_06a6ae6168ff456598d66371c865a555~mv2.jpeg', 'Analytics & Reporting', 'eatOS Staff', '2018-08-09', 'published'),
  ('improve-your-restaurant-delivery-system-in-3-steps', 'Improve Your Restaurant Delivery System.', 'With the COVID-19 pandemic still a huge threat and states reinstituting old lockdown orders as a result of rising case numbers, more and more restaurants are turning to online ordering platforms as reliable revenue...', '[{"type":"p","text":"With the COVID-19 pandemic still a huge threat and states reinstituting old lockdown orders as a result of rising case numbers, more and more restaurants are turning to online ordering platforms as reliable revenue streamsone of the few left since dine-in services keep being forced to reduce their capacity or shut down entirely."},{"type":"p","text":"Takeout and delivery actually make up a significant portion of sales now. Since the pandemic began, more than half of all customers have downloaded a new app to order food. Online ordering is more accurate than relying on a middleman and lets customers create their carts to their exact satisfaction. Why not open delivery to the public?"},{"type":"p","text":"The problem restaurants then come up against is how to properly cultivate a satisfactory customer experience when they never come face-to-face with the guests, which was previously a key component of foodservice. Fortunately, there are a few ways to tailor each customers experience even if the most interaction you have together is a few clicks on a webpage with a POS system for restaurants you can increase the customer experience."},{"type":"h2","text":"Revitalized Website"},{"type":"p","text":"A website that stands out draws guests further into your menu. Since reducing operations, you can minimize your options down to the best-sellers and those dishes with adaptable ingredients. Appeal to their visual senses with high-quality photos of your best food to give them an idea of what they could be having for dinner. Just make sure it really arrives in the promised condition, or you will get complaints."},{"type":"p","text":"The menu itself also needs to be appealing and unique. Make up clever, original names for your dishes and create telling but compelling descriptions so the food seems more appealing. You should also give guests the opportunity to build their own dish or at least make easy modifications to their cart. Specialized orders are very important to consumers nowadays, and allowing them to personalize their meal demonstrates care toward their individual allergies and preferences. This not only leaves you with more satisfied customers who are likely to return, but modifications increase the average check size too."},{"type":"h2","text":"Social Media"},{"type":"p","text":"Don’t miss any chance to connect with your guests. So much happens online that you’re missing a significant chunk of your potential audience by failing to advertise on the internet. Form strong, personal customer relationships by connecting directly to them on your Instagram, Facebook, and other social media channels. Ideally, you can even convince followers to make user-generated content, which is essentially free advertising and thus a huge benefit for you."},{"type":"h2","text":"Personalization"},{"type":"p","text":"Just because you can’t interact with your guests face to face doesn’t mean that you can’t deliver every order in a memorable way that encourages their return. Even a simple, handwritten thank-you note slipped into the container or a message on the side of the bag goes a long way toward showing your appreciation for loyal customers. If you’re feeling ambitious and you have the resources, give away some branded merchandise as a bonus gift such as a sticker or a reusable straw with the business’s name on it."},{"type":"p","text":"If you’re caught up with the modern age, then your restaurant also has a personalized branded QR code that takes customers to a mobile menu where they can browse and order right from their smartphones. Leave similar codes in the delivery bag with a promo code for a discount next time they buy directly from you, or have it link to a feedback page for them to leave a quick review. Whatever you decide, find a way to personalize each delivery so your customers are left with a positive impression of the restaurant, even if they can’t sit down and enjoy a meal in person."},{"type":"p","text":"Guests have a lot of options when it comes to online ordering. From what type of food to eat, to the restaurant they pick, to whether they should order via a third-party app, website, or another service, it all goes to show why it’s so vital for restaurants to make themselves stand apart from the competition."},{"type":"p","text":"Give yourself a competitive edge by streamlining your off-premise ordering system to handle an influx of eager new customers. Everybody’s finding creative methods to enjoy their favorite restaurants during this troubling time. Make sure yours is prepared to answer the call."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #eatOS #CoronavirusPandemic #OnlineOrdering #RestaurantBusiness #FoodDelivery"}]', 'https://static.wixstatic.com/media/a77ed6_8a12c449ace549f3ac8617e8b375c23d~mv2.jpeg', 'Online Ordering', 'eatOS Staff', '2018-08-02', 'published'),
  ('is-it-time-to-upgrade-your-point-of-sale', 'Is It Time to Upgrade Your Point of Sale?', 'Cash registers are an old, reliable and incredibly familiar aspect of the food service industry. Since restaurants were invented, people have been looking for better and better ways to count and keep track of their...', '[{"type":"p","text":"Cash registers are an old, reliable and incredibly familiar aspect of the food service industry. Since restaurants were invented, people have been looking for better and better ways to count and keep track of their profits. Although a long time has passed since restaurants began using registers, a lot of them still are, either because they never bothered or couldn’t afford to upgrade their technology. That is, until now."},{"type":"p","text":"There are a lot of downsides to relying on traditional old cash registers in this day and age, such as human error and slower table turn times. ?Modern technology makes operations more efficient and accurate than ever. Why should your restaurant make the switch to a POS system restaurant?"},{"type":"h2","text":"Fewer Errors"},{"type":"p","text":"Problems with the menu negatively impact customer experience which has a bad effect on profit. Human error is unavoidable, which is why automating as much of the dining experience as you can is a gateway to a more positive customer experience. With mobile and tableside ordering capabilities, customers can order right from their own phones or, alternatively, from devices set up on the table."},{"type":"p","text":"Ordering is easier and more accurate when servers input it directly into their tablets, because the orders go straight to the kitchen’s own screen. Special requirements like allergies are easy to input and track too. Orders are more accurate and wait times are shorter with advanced Point of Sales like the one powered by eatOS, so you can focus on a great customer experience."},{"type":"h2","text":"Inventory Tracking"},{"type":"p","text":"Avoid stocking issues and theft with inventory tracking capabilities. Forget manually watching over your inventory and taking time to count it every week. Inventory tracking features let you see which items are profitable, track how much you have on hand, automatically reorder items when you’re running low, rearrange your menu to maximize profit, and make sure till always matches the inventory."},{"type":"p","text":"The right Point of Sale lets you track orders and even create role permissions to determine who can void or comp items. Only managers should have control of that particular feature so servers can’t give free foods to themselves or friends without authorization."},{"type":"h2","text":"Menu Management"},{"type":"p","text":"Analyze sales data to craft the best possible menu. See which items are selling well and what’s costing you money, then make applicable design changes to either take low-selling items off completely or rearrange the whole menu to encourage more sales. Upselling capabilities also automatically prompt suggestions so staff members never miss a chance to offer a side or extra modification to the check."},{"type":"h2","text":"Reservations Made Easy"},{"type":"p","text":"Cash registers are just that: Places to sort and make cash transactions with customers. However they don’t have other capabilities, not like advanced Point of Sale systems do. Reservations have never been easier to handle than when you upgrade to a digital system instead. No more notes, written reminders or trouble managing the waitlist."},{"type":"p","text":"Put reservations online instead. With reservation management software, guests can book online or via the app, and the system can also automatically message them when their tables are ready. It’s good for management too, as the right software will let you more easily control your floor plan and tables, add notes to bookings to keep track of preferences or allergies, and analyze reports in real-time even when you’re not physically on the premises. Advanced Point of Sale systems also store guest data which lets you form customer profiles to better shape your marketing strategy and future guest interactions."},{"type":"h2","text":"Operations Management"},{"type":"p","text":"Handling your staff and business operations has never been easier. Streamline your schedule to avoid over- or understaffing which drives up labor costs or overworks your employees, respectively. Don’t let busy staff negatively impact customer service; invest in a Point of Sale that’s integrated with advanced scheduling software, like eatOS integrated with 7Shifts to save you the time and effort of scheduling. Let employees trade shifts virtually without managerial input so you can focus on bigger and better things."},{"type":"p","text":"Modern PoS systems also secure your data while actually increasing accessibility. eatOS stores data in the cloud so you don’t have to worry about break-ins or natural disasters risking your entire business. Instead, safe storage lets you access your information anytime and from anywhere that you’ve got internet."},{"type":"p","text":"The mobility of modern Point of Sale systems makes front of house workflow smoother than ever, in ways that traditional cash registers just can’t do. It’s not just about handling money anymore. In the modern age, you need a Point of Sale that doubles as a cash register and manages your workflow efficiently. Handheld and tablet devices are smoothing operations and changing the future of food service."},{"type":"p","text":"Cash registers may be cheaper upfront, but cost much more in the long run when you factor in labor and operational costs. Finding the right modern technology for your business is worth the time, money and effort it takes to shop around and train employees. Streamline your restaurant better than ever before; book a demo with eatOS to learn what we can do for your business. Down to the very last detail, eatOS makes sure that restaurant management has never been simpler."},{"type":"p","text":"#eatOS #PointofSaleforRestaurants #RestaurantBusiness #CloudTechnology #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_156a387b24bb4c6aa62b29d3d1264992~mv2.jpeg', 'Point of Sale', 'eatOS Staff', '2018-07-26', 'published'),
  ('who-is-eatos', 'Who Is eatOS?', 'At eatOS, we pride ourselves on working hard to bring restaurants, big or small, the most high-quality, state-of-the-art technology available on the market today. We believe that no matter the size of your business, if...', '[{"type":"p","text":"At eatOS, we pride ourselves on working hard to bring restaurants, big or small, the most high-quality, state-of-the-art technology available on the market today. We believe that no matter the size of your business, if it’s been in the family for generations or just came onto the scene in recent years, everybody deserves the accessibility and efficiency of an advanced Point of Sale system, as well as our associated devices."},{"type":"p","text":"Are you thinking about signing with eatOS? We’re proud to stand for values that resonate with serious business owners like you. When you partner with us, you’re joining a community of restaurateurs whose core values align with our own. At eatOS, we believe in:"},{"type":"p","text":"1. Accessibility. Having the means to acquire the best hard- and software available is critical to running smooth and efficient operations. Why should success beget success? Money shouldn’t be a barrier to good service, which is why we offer unbeatable prices for cutting-edge technologies, to put the power back in your hands."},{"type":"p","text":"2. Simplicity. Your technology should be a tool, not a hassle. We understand how difficult, time-consuming and laborious running a business is, and we believe that your restaurant technology should help raise your efficiency while taking the stress off your shoulders."},{"type":"p","text":"3. Innovation. While we offer the most cutting-edge features available, we also believe in constantly pushing the envelope to greater and greater heights. Why meet the competition where they’re at when you can transcend?"},{"type":"p","text":"4. Coherence. We design such easy-to-use interfaces so that you can manage all aspects of your business from one comprehensive screen. It’s easy to train on, too, so new hires get the hang of it quickly and you don’t spend excessive time or money on the recruitment process."},{"type":"p","text":"5. Intuitive. Why call tech support every time there’s an issue if you don’t have to? eatOS devices are straightforward so you can easily deduce and solve problems right then and there."},{"type":"p","text":"6. Intelligibility. We’ve made our devices as easy to understand as possible, but we still believe in clarity of vision. If there’s anything you need help with, our support team is ready 24/7 to fix the issue and get you back up and running."},{"type":"p","text":"7. Consistency. Get the same quality of service and product every single time. Your expectations don’t changeWhy should our solutions?"},{"type":"p","text":"8. Integrity. Serious business owners understand how important it is to be straightforward and transparent. eatOS believes in our strict code of conduct, and we never bend or compromise on these values so you get reliable, honest service every time."},{"type":"p","text":"We pride ourselves on being a business that you can rely on. eatOS runs with these core values in mind so you get high-quality services like the restaurant ordering system and state-of-the-art technology every time. If you’re interested in partnering with the eatOS team, sign up for a demo with us today. Let us show you how well apply these core values to your business and bring your restaurant into the future of food service."},{"type":"p","text":"#RestaurantTechnologyandCOVID19 #eatOS #RestaurantBusiness #CloudTechnology #Restaurants"}]', 'https://static.wixstatic.com/media/a77ed6_58b166b5cd2d4591b1dbf24c262c5ba0~mv2.jpeg', 'Point of Sale', 'eatOS Staff', '2018-07-19', 'published'),
  ('why-restaurants-need-sms-marketing', 'Why Restaurants Need SMS Marketing', 'Restaurants have changed how they market to customers. As digitization and contactless service rose during COVID-19, SMS marketing grew too. Some stores have already incorporated texting into their business model...', '[{"type":"p","text":"Restaurants have changed how they market to customers. As digitization and contactless service rose during COVID-19, SMS marketing grew too. Some stores have already incorporated texting into their business model somehow, to streamline reservations without a queue or order more conveniently. Now it’s becoming a popular marketing tool."},{"type":"p","text":"According to Bustle, people check their phones 160 times average each day. SMS marketing has a much higher chance of reaching your guests than other modes of contact. Connecting with customers via personal device requires careful planning, as well as a POS restaurant system that will work online and offline, with this technology you’ll get higher open rates that translate into sales."},{"type":"p","text":"It works best when combined with an integrated Point of Sale system that manages your marketing and guest information. Grow your customer base, reputation and overall success when you start using SMS marketing."},{"type":"p","text":"Photo by Alex Ware on Unsplash"},{"type":"h2","text":"Why Customers Prefer It"},{"type":"p","text":"With texts, guests have a more streamlined and transparent dining experience from start to finish. They can track their order’s status if they get takeout or delivery, which gives them a better grip on ETA. Since people tend to keep their phones on hand, sending deals and promotions right to their pockets will encourage them to drop by. Then, they can pull up the code right there instead of digging around or having to remember to bring in a physical coupon. The ease and efficiency of SMS marketing supports customer satisfaction and retention long-term."},{"type":"p","text":"Encourage guests to opt-in to SMS marketing by pushing deals and promotions that only apply if they’re signed up. Every other week or so, maybe send out a unique code just to SMS customers. This way, sales rise and you can also track how text message marketing converts into orders. Advertise the new platform on your social media to inspire more sign-ups."},{"type":"h2","text":"SMS Marketing Best Practices"},{"type":"p","text":"Although it’s a great tool, make sure that customers explicitly opt-in before you start texting them. Texting is personal, so customers don’t want to be suddenly contacted by businesses out of the blue. Often, there are laws in place about putting people on marketing lists without their permission anyway. Always have customers opt into SMS marketing first."},{"type":"p","text":"Timing also matters. Don’t interrupt sleep or dinnertime with promotions; in general, it’s best to stick to business hours. Getting promo codes an hour before lunch break will get customers thinking about your menu right as the hunger sets in."},{"type":"p","text":"Showcase your brand clearly and immediately in all your messages so they know who’s texting. If your restaurant is powered by a smart Point of Sale system, you can enable text-to-pay that lets them finish their transaction contact-free too. Create a completely modernized experience with a POS that handles marketing, orders, and payment from one centralized hub. Customer satisfaction and loyalty start here."},{"type":"p","text":"eatOS offers an all-in-one cloud-based eco-system exclusively for restaurants. From Point of Sale to Contactless Ordering, Pay & Order at Table, Kitchen Display System, Guest Facing Display, Online Ordering APP / Website and Workforce Management there is everything to help a restaurant succeed no matter the size. Click Here to Schedule a demo to learn more about how your restaurant can make a smooth transition into the world of restaurant technology made simple."},{"type":"p","text":"#RestaurantMarketing #eatOS #PointofSaleforRestaurants #SMSMarketing #RestaurantBusiness #Restaurant"}]', 'https://static.wixstatic.com/media/a77ed6_a9ccded1165448c79036f62327d836d2~mv2.jpg', 'Marketing & Loyalty', 'eatOS Staff', '2018-07-12', 'published');
